mapper.select:
SELECT ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else ETR_ENTRUST_ADD.ASSET_TYPE_10 end finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId, case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, if(ETR_ENTRUST_ADD.ASSET_TYPE='F01',IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), if(ETR_ENTRUST_ADD.ASSET_TYPE='F10',IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0),IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM))) entrustAmt, if(ETR_ENTRUST_ADD.ASSET_TYPE='F01',IFNULL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0), if(ETR_ENTRUST_ADD.ASSET_TYPE='F10',IFNULL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),IFNULL(ETR_FINISH_STATUSA.FINISH_AMT,0))) finishAmt, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, B.TRADER trader, ETR_ENTRUST.REMARK remark, CASE WHEN FP.FINPROD_ID IS NOT NULL THEN '01' ELSE '02' END xyFlag FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT group_concat(TRADER, ',') TRADER, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_MARKET_ID = ETR_ENTRUST.STOCK_ID and FP.FINPROD_TYPE2 = ETR_ENTRUST.FINPROD_TYPE2
AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn})
AND ETR_ENTRUST_ADD.ASSET_TYPE IN(
#{item}
)
AND ETR_ENTRUST.INV_MANAGER_ID = #{invManagerId}
AND (ETR_ENTRUST.PORTFOLIO_ID LIKE concat_ws('', '%',#{portfolioId,jdbcType=VARCHAR},'%') OR PTL_PORTFOLIO.PORTFOLIO_NAME LIKE concat_ws('', '%',#{portfolioId,jdbcType=VARCHAR},'%'))
AND ETR_ENTRUST.ENTRUST_ID LIKE concat_ws('', '%',#{entrustId,jdbcType=VARCHAR},'%')
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN(
#{item}
)
AND ((FIN_PRODUCT.FINPROD_MARKET_ID LIKE concat_ws('', '%',#{finprodId,jdbcType=VARCHAR},'%') OR FIN_PRODUCT.FINPROD_ABBR LIKE concat_ws('', '%',#{finprodId,jdbcType=VARCHAR},'%')) OR (ETR_ENTRUST_ADD.ASSET_TYPE_10 LIKE concat_ws('', '%',#{finprodId,jdbcType=VARCHAR},'%') OR OPT_TARGET_INFO.TARGET_NAME LIKE concat_ws('', '%',#{finprodId,jdbcType=VARCHAR},'%')) )
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST.CCY = #{ccy}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus}
AND DATE_FORMAT(ETR_ENTRUST.VDATE,'%Y-%m-%d') >= #{vdateBegin}
AND DATE_FORMAT(ETR_ENTRUST.VDATE,'%Y-%m-%d') <= #{vdateEnd}
AND DATE_FORMAT(ETR_ENTRUST.MDATE,'%Y-%m-%d') >= #{mdateBegin}
AND DATE_FORMAT(ETR_ENTRUST.MDATE,'%Y-%m-%d') <= #{mdateEnd}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND ETR_ENTRUST_ADD.BUSI_PS = #{busiPs}
union all SELECT ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST.FINPROD_TYPE2 finprodType2, ETR_ENTRUST.FINPROD_ID finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId, ETR_ENTRUST_ADD.ASSET_TYPE_11 finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, if(ETR_ENTRUST_ADD.ASSET_TYPE='F01',IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), if(ETR_ENTRUST_ADD.ASSET_TYPE='F10',IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0),IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM))) entrustAmt, if(ETR_ENTRUST_ADD.CONTRACT_RESULT='已签署完毕',ETR_ENTRUST.ENTRUST_AMT,0) finishAmt, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, B.TRADER trader, ETR_ENTRUST.REMARK remark, '02' xyFlag FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT group_concat(TRADER, ',') TRADER, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID
AND ETR_ENTRUST.FINPROD_TYPE2 = 'F36' AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn})
AND ETR_ENTRUST_ADD.ASSET_TYPE IN(
#{item}
)
AND ETR_ENTRUST.INV_MANAGER_ID = #{invManagerId}
AND (ETR_ENTRUST.PORTFOLIO_ID LIKE concat_ws('', '%',#{portfolioId,jdbcType=VARCHAR},'%') OR PTL_PORTFOLIO.PORTFOLIO_NAME LIKE concat_ws('', '%',#{portfolioId,jdbcType=VARCHAR},'%'))
AND ETR_ENTRUST.ENTRUST_ID LIKE concat_ws('','%',#{entrustId,jdbcType=VARCHAR},'%')
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN(
#{item}
)
AND (FIN_PRODUCT.FINPROD_MARKET_ID LIKE concat_ws('','%',#{finprodId,jdbcType=VARCHAR},'%') OR FIN_PRODUCT.FINPROD_ABBR LIKE concat_ws('','%',#{finprodId,jdbcType=VARCHAR},'%'))
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST.CCY = #{ccy}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus}
AND DATE_FORMAT(ETR_ENTRUST.VDATE,'%Y-%m-%d') >= #{vdateBegin}
AND DATE_FORMAT(ETR_ENTRUST.VDATE,'%Y-%m-%d') <= #{vdateEnd}
AND DATE_FORMAT(ETR_ENTRUST.MDATE,'%Y-%m-%d') >= #{mdateBegin}
AND DATE_FORMAT(ETR_ENTRUST.MDATE,'%Y-%m-%d') <= #{mdateEnd}
AND ETR_ENTRUST_ADD.BUSI_PS = #{busiPs}

SELECT DISTINCT SYS_USER.USER_NAME userName, concat_ws('', '(' ,SYS_USER.USER_NAME , ')' , SYS_USER.REAL_NAME ) realName FROM SYS_USER INNER JOIN SYS_USER_ROLE ON SYS_USER.USER_NAME = SYS_USER_ROLE.USER_ID INNER JOIN SYS_ROLE ON SYS_USER_ROLE.ROLE_ID = SYS_ROLE.ROLE_ID
AND SYS_ROLE.ROLE_POS IN(
#{item}
)
